protected void new()
{
    // call service class and service class method
    super(classStr(METAP68EmailFailureService), methodStr(METAP68EmailFailureService, processOperation), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Construct METAP68EmailFailureController class
/// </summary>
public static METAP68EmailFailureController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METAP68EmailFailureController controller;
    controller = new METAP68EmailFailureController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

    public static void main(Args _args)

    {
        METAP68EmailFailureController controller;

        controller = METAP68EmailFailureController::construct();
        controller.parmArgs(_args);
        controller.parmShowDialog(true);
        controller.startOperation();
    }

/// <summary>
/// Caption of a batch job
/// </summary>
public ClassDescription defaultCaption()
{
    return "@MET:AP68EmailFailureNotification";
}
